5148\u505a\u56fa\u5b9a\u9884\u70ed\u6b65(\u5efa\u8bae \u22653 \u6b21\u5b8c\u6574 vmapped step \u8c03\u7528)+ jax.block_until_ready \u786e\u8ba4\u7f16\u8bd1\u5b8c\u6210,\u518d\u5f00\u59cb\u8ba1\u65f6;\u7f16\u8bd1\u65f6\u95f4\u5355\u72ec\u62a5\u544a\u3002\n  (b) reset:\u9884\u70ed\u9636\u6bb5\u5b8c\u6210 reset,\u4e3b\u8ba1\u65f6\u5faa\u73af\u4e0d\u542b reset;\u53e6\u8bbe\"\u542b reset \u7684 episode \u53e3\u5f84\"\u4f5c\u4e3a\u6b21\u8981\u62a5\u544a\u9879(\u6bcf max_steps \u6b65\u63d2\u5165\u4e00\u6b21 vmap \u5316\u7684 reset)\u3002\n  (c) \u52a8\u4f5c\u62bd\u6837:\u4e3b\u53e3\u5f84\"\u7eaf\u6b65\u8fdb\"(\u52a8\u4f5c\u5f20\u91cf\u5728\u8ba1\u65f6\u533a\u5916\u4e00\u6b21\u6027\u9884\u751f\u6210,\u4e24\u4fa7\u540c\u89c4\u5219);\u6b21\u53e3\u5f84\"\u542b\u62bd\u6837\u6b65\u8fdb\"(\u6bcf\u6b65\u6309\u540c\u4e00\u5206\u5e03\u73b0\u573a\u62bd\u6837)\u4e5f\u5206\u522b\u62a5\u544a,\u4ee5\u4fbf\u5206\u79bb\u5f00\u9500\u3002\n  (d) \u6570\u7ec4\u8f6c\u6362/\u4e3b\u673a\u2014\u8bbe\u5907\u62f7\u8d1d:JAX \u4fa7\u8ba1\u65f6\u533a\u5185\u5fc5\u987b\u4ee5 jax.block_until_ready \u6536\u5c3e(\u5426\u5219\u6d4b\u7684\u662f\u5f02\u6b65\u6d3e\u53d1,\u65e0\u610f\u4e49);CPU\u2192\u8bbe\u5907\u62f7\u8d1d\u4ec5\u5728\u542b reset/\u6570\u636e\u6ce8\u5165\u53e3\u5f84\u4e2d\u8ba1\u5165\u3002\n- \u805a\u5408\u5355\u4f4d:\u4e24\u4e2a\u541e\u5410\u5206\u5f00\u62a5\u544a\u2014\u2014JAX \u4fa7\"\u805a\u5408\u541e\u5410 = V\u00d7\u6279\u6b65\u6570/\u79d2\"\u4e0e\"\u6bcf\u526f\u672c\u541e\u5410\";CPU \u4fa7\"\u5355\u73af\u5883\u541e\u5410\"\u4e0e(\u82e5\u505a\u591a\u8fdb\u7a0b)\"\u591a\u8fdb\u7a0b\u805a\u5408\u541e\u5410\"\u3002\u52a0\u901f\u6bd4\u53ea\u5728\u540c\u4e00\u805a\u5408\u53e3\u5f84\u4e0b\u8ba1\u7b97\u3002\n\n2. \u4e24\u4fa7\u5bf9\u9f50\u7684\u5bf9\u7167\u6761\u4ef6(\u5168\u90e8\u663e\u5f0f\u56fa\u5b9a,\u5199\u5165\u914d\u7f6e\u6e05\u5355)\n- \u573a\u666f\u914d\u7f6e:agent \u6570 N\u3001landmark \u6570 L\u3001\u89c2\u6d4b/\u52a8\u4f5c\u7ef4\u5ea6\u3001max_steps \u5b8c\u5168\u4e00\u81f4\u300