f0f\u81ea\u53d8\u91cf\u7684\u541e\u5410\u626b\u63cf;\n- \"Simple Spread \u73af\u5883\" \u2192 D4 \u4e24\u4fa7\u5171\u4eab\u7684\u5355\u4e00\u56fa\u5b9a\u573a\u666f\u914d\u7f6e(\u6570\u503c\u6765\u6e90=\u8bbe\u8ba1\u9009\u62e9\u00b7\u5f85\u6838),D6 \u654f\u611f\u6027\u5c0f\u8282\u8986\u76d6 N \u53d8\u5316;\n- \"\u539f\u59cb CPU \u5bf9\u5e94\u7269\" \u2192 \u6765\u6e90\u652f\u6301\u4e8b\u5b9e F7:\u9879\u76ee\u4e0a\u4e0b\u6587\u5c06\u539f\u59cb CPU \u57fa\u7ebf\u660e\u786e\u5217\u4e3a \"Original CPU-Based Implementations: MPE (Multi-Agent Particle Environment) from PettingZoo\",\u6545\u4e3b\u57fa\u7ebf\u9501\u5b9a PettingZoo mpe/simple_spread_v2(\u5355\u7ebf\u7a0b\u5355\u73af\u5883;\u591a\u8fdb\u7a0b\u4e3a\u9644\u8868\u53e3\u5f84);\n- \"steps-per-second\" \u2192 D3 \u8ba1\u65f6\u4e0e\u805a\u5408\u53e3\u5f84(\u805a\u5408\u541e\u5410/\u6bcf\u526f\u672c\u541e\u5410/\u5355\u73af\u5883\u541e\u5410\u5206\u5217);\n- \"\u6bd4\u8f83\" \u2192 D6 \u52a0\u901f\u6bd4\u5b9a\u4e49 + bootstrap \u5224\u636e,\u53e0\u52a0 D8 \u4e09\u5c42\u7ed3\u8bba\u5206\u533a(\u7532/\u4e59/\u4e19)\u660e\u786e\"\u672c\u73af\u5883\u53ef\u56de\u7b54\u4ec0\u4e48\u3001\u4e0d\u53ef\u56de\u7b54\u4ec0\u4e48\"\u3002\n\n\u25a0 D1 \u8bbe\u8ba1\u7406\u7531\u4e0e\u95ee\u9898\u754c\u5b9a\n\u6027\u80fd\u95ee\u9898\u53ea\u5728\"\u540c\u4e00\u73af\u5883\u8bed\u4e49\u3001\u540c\u4e00\u968f\u673a\u7b56\u7565\u3001\u540c\u4e00\u786c\u4ef6\u4e0e\u9694\u79bb\u89c4\u5219\u3001\u663e\u5f0f\u5e76\u884c\u5ea6\u81ea\u53d8\u91cf\"\u56db\u4e2a\u6761\u4ef6\u4e0b\u624d\u6709\u53ef\u6bd4\u6027\u3002\u672c\u8bbe\u8ba1\u628a\u4e00\u5207\u672a\u7531\u8d44\u6599\u7ed9\u5b9a\u7684\u91cf\u964d\u683c\u4e3a\u663e\u5f0f\u8bbe\u8ba1\u81ea\u53d8\u91cf\u6216\u6807\u6ce8\"\u5f85\u6838\"\u7684\u4e00\u5207\u53c2\u6570\u5316\u9009\u62e9,\u4ee5\u4fdd\u8bc1\u6bd4\u8f83\u7ed3\u8bba\u5185\u90e8\u4e00\u81f4\u3001\u5916\u90e8\u53ef\u590d\u6838\u3002\u672c\u4efb\u52a1\u4e3a design-only \u8f68\u9053:\u4ea4\u4ed8\u8bbe\u8ba1\u3001\u53ef\u884c\u6027\u8bba\u8bc1\u4e0e\u53ef\u6267\u884c\u89c4\u7a0b,\u4e0d\u4ea4\u4ed8\u5b9e\u6d4b\u6570\u5b57\u3002\n\n\u25a0 D2 \u6765\u6e90\u4e0e\u6750\u6599\u68c0\u67e5\u62a5\u544a\n- \u5de5\u4f5c\u533a:/workspace \u4ec5 task.json(8KB);\u5168\u76d8\u68c0\u7d22\u65e0 jaxmarl/simple_spread/pettingzoo/mpe \u4efb\u4f55\u526f\u672c(\u547d\u4ee4\u4e0e\u7ed3\u679c\u89c1 D7 \u8bc1\u636e\u94fe)\u3002\u2192 \u65e0\u53ef\u8fd0\u884c\u4ee3\u7801\u6811,\u65e0\u8def\u5f84\u53ef\u5f15\u7528\u3002\n- \u7248\u672c\u6807\u8bc6:\u672a\u786e\u5b9a(\u65e0 setup.py/pyproject.toml/requirements.txt/__version__/lock \u6587\u4ef6)\u3002\u4e0a\u6e38\u4ed3\u5e93\u5730\u5740(flairox/jaxmarl\u3001Farama-Foundation/PettingZoo\u3001openai/mpe)\u4ec5\u4e3a\u5916\u90e8\u77e5\u8bc6\u5019\u9009,\u672c\u73af\u5883\u65e0\u7f51\u7edc\u4e0d\u53ef\u6838\u5b9e\u3002\n- \u73af\u5883\u72b6\u6001(Python 3.14.4\u3001224 \u6838\u3001\u4f9d\u8d56\u5168\u7f3a\u3001\u65e0 GPU\u3001\u65e0\u7f51\u7edc)\u89c1 D7\u3002\n\n\u25a0 D3 \u6d4b\u91cf\u5b9a\u4e49:step\u3001\u8ba1\u65f6\u8fb9\u754c\u3001\u805a\u5408\u5355\u4f4d\n- \u73af\u5883\u6b65(env step):\u5bf9\u5168\u90e8 agent \u5404\u65bd\u52a0\u4e00\u6b21\u52a8\u4f5c\u5e76\u63a8\u8fdb\u4e00\u6b21\u52a8\u529b\u5b66+\u5956\u52b1\u8ba1\u7b97\u3002CPU \u4fa7\u4e00\u6b21 env.step(joint_action)=1 env step;JAX \u4fa7\u4e00\u6b21 vmapped step=V \u4e2a env steps(=1 \u6279\u6b65)\u3002\n- \u8ba1\u65f6\u8fb9\u754c(\u4e24\u4fa7\u540c\u89c4\u5219):\n  (a) JIT \u7f16\u8bd1\u6392\u9664\u5728\u8ba1\u65f6\u5916:\u9884\u70ed \u22653 \u6b21\u5b8c\u6574 vmapped step \u5e76 jax.block_until_ready \u540e\u5f00\u59cb\u8ba1\u65f6;\u7f16\u8bd1\u8017\u65f6\u5355\u72ec\u8bb0\u5f55\u3001\u5355\u72ec\u62a5\u544a;\n  (b) \u4e3b\u53e3\u5f84\u8ba1\u65f6\u5faa\u73af\u4e0d\u542b reset(\u9884\u70ed\u9636\u6bb5\u5b8c\u6210);\u6b21\u53e3\u5f84\"episode \u7ea7\"\u6bcf max_steps \u6b65\u6267\u884c\u4e00\u6b21 vmap \u5316 reset \u5e76\u8ba1\u5165,\u5355\u72ec\u6210\u8868;\n  (c) \u4e3b\u53e3\u5f84\u52a8\u4f5c\u5f20\u91cf\u5728\u8ba1\u65f6\u533a\u5916\u9884\u751f\u6210(\u4e24\u4fa7\u540c\u89c4\u5219);\u6b21\u53e3\u5f84\u9010\u6b65\u73b0\u573a\u62bd\u6837,\u5355\u72ec\u62a5\u544a\u4ee5\u5206\u79bb\u62bd\u6837\u5f00\u9500;\n  (d) JAX \u8ba1\u65f6\u533a\u5fc5\u987b\u4ee5 jax.block_until_ready \u6536\u5c3e(\u907f\u514d\u6d4b\u5f97\u5f02\u6b65\u6d3e\u53d1);\u4e3b\u673a\u2014\u8bbe\u5907\u62f7\u8d1d\u4ec5\u5728\u542b reset/\u6ce8\u5165\u53e3\u5f84\u8ba1\u5165;CPU \u4fa7\u7edf\u4e00 time.perf_counter\u3002\n- \u805a\u5408\u5355\u4f4d(\u5206\u5217\u62a5\u544a,\u7981\u6b62\u6df7\u7528):JAX \u805a\u5408\u541e\u5410 = V\u00d7\u6279\u6b65\u6570/\u79d2;JAX \u6bcf\u526f\u672c\u541e\u5410;CPU \u5355\u73af\u5883\u541e\u5410(\u4e3b\u57fa\u7ebf);CPU \u591a\u8fdb\u7a0b\u805a\u5408\u541e\u5410(\u9644\u8868,\u6807\u6ce8\u7cfb\u7edf\u7ea7\u53e3\u5f84)\u3002\n\n\u25a0 D4 \u5bf9\u7167\u4e0e\u63a7\u5236\u6761\u4ef6\u8868(\u5168\u90e8\u663e\u5f0f\u56fa\u5b9a)\n1. \u573a\u666f\u914d\u7f6e(\u4e3b\u8868\u5355\u4e00\u56fa\u5b9a\u914d\u7f6e;\u6570\u503c\u6765\u6e90=\u8bbe\u8ba1\u9009\u62e9\u00b7\u5f85\u6838,\u5019\u9009\u503c\u4ec5\u4e3a\u5916\u90e8\u77e5\u8bc6/\u5f85\u6838\u5b9e\u5217\u4e3e):\n   \u667a\u80fd\u4f53\u6570 N=3(\u5019\u9009 {3,5});\u5730\u6807\u6570 L=5(\u5019\u9009\u5217\u4e3e:\u4e0e N \u76f8\u7b49\u7684\u573a\u666f\u4ea6\u5b58\u5728);episode \u957f\u5ea6 max_steps=100(\u5019\u9009 {25,100});\u52a8\u4f5c\u7a7a\u95f4:\u79bb\u6563 5 \u52a8\u4f5c(\u4e3b\u53e3\u5f84;\u5019\u9009:\u8fde\u7eed\u4e8c\u7ef4\u52a8\u4f5c)\u3002\u4ee5\u4e0a\u4efb\u4f55\u6570\u5b57\u5747\u4e0d\u5f97\u4ee5\"\u8bba\u6587\u53c2\u6570\"\u540d\u4e49\u5f15\u7528\u3002\n2. \u968f\u673a\u7b56\u7565:\u79bb\u6563\u4e3b\u53e3\u5f84\u2014\u2014\u6bcf agent \u6bcf\u6b65\u72ec\u7acb\u5747\u5300\u62bd\u6837\u4e8e {0,1,2,3,4};\u8fde\u7eed\u5907\u9009\u2014\u2014\u6bcf\u7ef4\u72ec\u7acb Uniform[-1,1]\u3002\u79bb\u6563\u4e0e\u8fde\u7eed\u4e4b\u9009\u62e9=\u5047\u8bbe;\u8ba1\u65f6\u5f71\u54cd(\u4ec5\u65b9\u5411\u6027,\u8bbe\u8ba1\u63a8\u6f14):\u79bb\u6563\u4e3a\u67e5\u8868\u5f0f\u91c7\u6837\u3001\u8fde\u7eed\u4e3a\u6d6e\u70b9\u5411\u91cf\u91c7\u6837,\u4e8c\u8005\u5728\u4e24\u4fa7\u5747\u8fdc\u5c0f\u4e8e\u6b65\u8fdb\u672c\u4f53\u5f00\u9500,\u4e14\u4e3b\u53e3\u5f84\u5df2\u628a\u91c7\u6837\u79fb\u51fa\u8ba1\u65f6\u533a,\u6545\u6b64\u9009\u62e9\u5bf9\u4e3b\u8868\u5f71\u54cd\u9884\u671f\u53ef\u5ffd\u7565,\u5bf9\u6b21\u53e3\u5f84\u5f71\u54cd\u4e3a\u5c0f\u5e45\u5e38\u6570\u9879\u3002\n3. \u79cd\u5b50\u5bf9\u9f50:\u540c\u4e00\u6574\u6570\u79cd\u5b50\u5e8f\u5217\u5582\u7ed9\u4e24\u4fa7\u5404\u81ea\u6807\u51c6\u62bd\u6837\u5668(JAX:PRNGKey(seed+i) \u786e\u5b9a\u6027 key \u5e8f\u5217;CPU:numpy Generator(seed));\u5df2\u77e5\u9650\u5ea6:\u4e24\u4fa7\u968f\u673a\u6d41\u975e\u9010\u4f4d\u4e00\u81f4,\u8bb0\u5165\u5c40\u9650\u3002\n4. \u8fed\u4ee3\u4e0e\u91cd\u590d:\u6bcf\u914d\u7f6e\u8ba1\u65f6\u65f6\u957f\u4e0b\u9650 \u226510 s \u91cf\u7ea7\u3001R=7 \u6b21\u91cd\u590d(\u5747\u5df2\u7ecf\u60a8\u6279\u51c6;\u4ecd\u6807\u6ce8\u4e3a\u8bbe\u8ba1\u9009\u62e9)\u3002\n5. \u786c\u4ef6\u4e0e\u9694\u79bb:\u540c\u4e00\u53f0\u673a\u5668;\u4e24\u4fa7\u7edd\u4e0d\u540c\u65f6\u8fd0\u884c;CPU \u4fa7 OMP/MKL \u7ebf\u7a0b\u6570=1\u3001taskset \u7ed1\u5355\u6838;JAX \u4fa7\u56fa\u5b9a\u5355\u8bbe\u5907\u4e0e\u7ebf\u7a0b\u73af\u5883\u53d8\u91cf;\u91cd\u590d\u95f4\u51b7\u5374\u95f4\u9694(\u8bbe\u8ba1\u9009\u62e9);\u5c3d\u529b\u8bb0\u5f55 CPU \u8c03\u9891/\u8d1f\u8f7d\u4f5c\u4e3a\u534f\u53d8\u91cf\u3002\n6. \u9884\u70ed\u4e0e\u4e22\u5f03:\u4e24\u4fa7\u5404\u81ea\u9884\u70ed\u6bb5(\u6b65\u6570/\u65f6\u957f\u5199\u5165\u914d\u7f6e\u6e05\u5355)\u540e\u4e22\u5f03,\u518d\u8fdb\u5165\u8ba1\u65f6\u91cd\u590d\u3002\n\n\u25a0 D5 \u5e76\u884c\u5ea6\u81ea\u53d8\u91cf\u8bbe\u8ba1\n- JAX \u4fa7:V \u2208 {1, 16, 64, 256, 1024, 4096, 8192} \u5e42\u6b21\u7f51\u683c;\u663e\u5f0f\u58f0\u660e:\u8be5\u7f51\u683c\u975e\u8bba\u6587\u590d\u73b0\u503c,\u800c\u662f\u4e3a\u523b\u753b\"\u541e\u5410\u2014\u5e76\u884c\u5ea6\"\u66f2\u7ebf\u800c\u8bbe\u7684\u626b\u63cf;\u5b9e\u9645\u5